const COUNT_COUPLES = [
  ['latRings', 'lonDensity'],
  ['rings', 'lonDensity'],
  ['lanes', 'segs'],
]
const COUNT_KEYS = ['orbitN', 'ghostN', 'nodeN', 'strandN', 'signals']
const DENSITY_KEYS = ['iconD']
const SIZE_KEYS = ['rBase', 'rDepth', 'rActive', 'rDot', 'ghostR', 'partR', 'partRDepth', 'nodeR', 'nodeRDepth']

function scaleCounts(config: BaseConfig, factor: number): BaseConfig {
  const result = { ...config }
  const visited = new Set<string>()
  const sqrtFactor = Math.sqrt(factor)

  for (const [k1, k2] of COUNT_COUPLES) {
    if (result[k1] != null && result[k2] != null && !visited.has(k1) && !visited.has(k2)) {
      result[k1] = Math.max(2, Math.round(result[k1] * sqrtFactor))
      result[k2] = Math.max(2, Math.round(result[k2] * sqrtFactor))
      visited.add(k1)
      visited.add(k2)
    }
  }

  for (const k of COUNT_KEYS) {
    if (result[k] != null && result[k] !== 0 && !visited.has(k)) {
      result[k] = Math.max(1, Math.round(result[k] * factor))
    }
  }

  for (const k of DENSITY_KEYS) {
    if (result[k] != null) {
      result[k] = Math.max(0.02, result[k] * factor)
    }
  }

  return result
}

function scaleSizes(config: BaseConfig, factor: number): BaseConfig {
  const result = { ...config }
  for (const k of SIZE_KEYS) {
    if (result[k] != null) {
      result[k] = result[k] * factor
    }
  }
  return result
}

export function presetFor(mode: ThinkingOrbMode, pixelSize: number): { speed: number; opts: BaseConfig } {
  const preset = SCALE_PRESETS[mode]
  const t = clamp((pixelSize - 20) / 44)
  const countScale = lerp(preset.small.count, preset.large.count, t)
  const sizeScale = lerp(preset.small.size, preset.large.size, t)

  let opts: BaseConfig = { ...DEFAULT_CONFIGS[mode] }
  if (countScale !== 1) opts = scaleCounts(opts, countScale)
  if (sizeScale !== 1) opts = scaleSizes(opts, sizeScale)

  if (preset.small.extra) {
    const extra: Record<string, number> = {}
    for (const key of Object.keys(preset.small.extra)) {
      extra[key] = lerp(preset.small.extra[key], preset.large.extra![key], t)
    }
    opts = { ...opts, ...extra }
  }

  return {
    speed: lerp(preset.small.speed, preset.large.speed, t),
    opts,
  }
}

/**
 * Mathematical utilities and noise functions for procedural 3D particle rendering
 */

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

export function fract(x: number): number {
  return x - Math.floor(x)
}

export function clamp(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x
}

export function smoothstep(x: number): number {
  return x * x * (3 - 2 * x)
}

export function hash(x: number, y: number): number {
  const n = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return n - Math.floor(n)
}

export function valueNoise2D(x: number, y: number): number {
  const xi = Math.floor(x)
  const yi = Math.floor(y)
  let xf = x - xi
  let yf = y - yi
  xf = xf * xf * (3 - 2 * xf)
  yf = yf * yf * (3 - 2 * yf)
  const bl = hash(xi, yi)
  const br = hash(xi + 1, yi)
  const tl = hash(xi, yi + 1)
  const tr = hash(xi + 1, yi + 1)
  return bl + (br - bl) * xf + (tl - bl) * yf + (bl - br - tl + tr) * xf * yf
}

/**
 * Distribute points evenly on a 3D sphere using the golden spiral (Fibonacci sphere)
 */
export function fibonacciSphere(i: number, n: number): [number, number, number] {
  const phi = Math.PI * (3 - Math.sqrt(5))
  const y = 1 - 2 * ((i + 0.5) / n)
  const radius = Math.sqrt(Math.max(0, 1 - y * y))
  const theta = i * phi
  return [radius * Math.cos(theta), y, radius * Math.sin(theta)]
}

export function angleDelta(a: number, b: number): number {
  return Math.atan2(Math.sin(a - b), Math.cos(a - b))
}

/**
 * Perspective-correct 3D rotation transform projector
 */
export function create3DRotation(rotY: number, rotX: number, cx: number, cy: number, scale: number) {
  const sinX = Math.sin(rotX)
  const cosX = Math.cos(rotX)
  const sinY = Math.sin(rotY)
  const cosY = Math.cos(rotY)

  return (x: number, y: number, z: number): [number, number, number] => {
    const xRotY = x * cosY + z * sinY
    const zRotY = -x * sinY + z * cosY
    const yRotX = y * cosX - zRotY * sinX
    const zRotX = y * sinX + zRotY * cosX
    return [cx + xRotY * scale, cy - yRotX * scale, zRotX]
  }
}

export function responsiveScale(px: number, power: number): number {
  return Math.pow(px / 300, power)
}

export interface RenderDot {
  x: number
  y: number
  z: number
  r: number
  white: number
  a?: number
}

export interface RenderLine {
  x1: number
  y1: number
  x2: number
  y2: number
  white: number
  a?: number
  w: number
}

export interface RenderPassData {
  dots: RenderDot[]
  lines: RenderLine[]
}

export function drawDots(ctx: CanvasRenderingContext2D, dots: RenderDot[], isDarkSurface: boolean) {
  for (const dot of dots) {
    const alpha = dot.a ?? 1
    const white = Math.min(1, Math.max(0, dot.white))
    // On dark surface (isDarkSurface = true), white value of 0.72 becomes (1 - 0.72)*255 = 71 (faint),
    // and white value of 0.05 becomes (1 - 0.05)*255 = 242 (bright white highlight).
    const gray = Math.round((isDarkSurface ? 1 - white : white) * 255)
    ctx.fillStyle = `rgba(${gray},${gray},${gray},${alpha})`
    ctx.beginPath()
    ctx.arc(dot.x, dot.y, dot.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

export function drawLines(ctx: CanvasRenderingContext2D, lines: RenderLine[], isDarkSurface: boolean) {
  for (const line of lines) {
    const alpha = line.a ?? 1
    const white = Math.min(1, Math.max(0, line.white))
    const gray = Math.round((isDarkSurface ? 1 - white : white) * 255)
    ctx.strokeStyle = `rgba(${gray},${gray},${gray},${alpha})`
    ctx.lineWidth = line.w
    ctx.beginPath()
    ctx.moveTo(line.x1, line.y1)
    ctx.lineTo(line.x2, line.y2)
    ctx.stroke()
  }
}

export function filterAndSortElements(dots: RenderDot[], lines: RenderLine[], minRadius = 0.3): RenderPassData {
  const validDots: RenderDot[] = []
  for (const dot of dots) {
    if ((dot.a ?? 1) < 0.02) continue
    dot.r = Math.max(minRadius, dot.r)
    validDots.push(dot)
  }
  validDots.sort((a, b) => a.z - b.z)
  return {
    dots: validDots,
    lines: lines.filter((l) => (l.a ?? 1) >= 0.02),
  }
}

export function renderOrbScene(ctx: CanvasRenderingContext2D, scene: RenderPassData, isDarkSurface: boolean) {
  if (scene.lines.length) {
    drawLines(ctx, scene.lines, isDarkSurface)
  }
  drawDots(ctx, scene.dots, isDarkSurface)
}

export function setupCanvasDpr(
  canvas: HTMLCanvasElement,
  cssWidth: number,
  cssHeight: number,
): { ctx: CanvasRenderingContext2D; w: number; h: number } {
  const dpr = Math.min(2, (typeof window !== 'undefined' && window.devicePixelRatio) || 1)
  const w = Math.max(1, Math.round(cssWidth))
  const h = Math.max(1, Math.round(cssHeight))

  const physW = Math.round(w * dpr)
  const physH = Math.round(h * dpr)

  if (canvas.width !== physW || canvas.height !== physH) {
    canvas.width = physW
    canvas.height = physH
  }

  const ctx = canvas.getContext('2d')!
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  return { ctx, w, h }
}
